/*insertMasterCmClSBDtimain*/

		INSERT INTO XXSB_DTI_MAIN
		( 
		    CONVERSATION_ID 
		  , SUPBUY_TYPE 
		  , DIRECTION 
		  , DTI_WDATE 
		  , DTI_TYPE 
		  , TAX_DEMAND 
		  , ISSUE_ID 
		  , SEQ_ID 
		  , SUP_COM_REGNO 
		  , SUP_REP_NAME 
		  , SUP_COM_NAME 
		  , SUP_COM_CLASSIFY
		  , SUP_COM_ADDR
		  , SUP_EMP_NAME
		  , SUP_EMAIL
		  , BYR_COM_REGNO
		  , BYR_REP_NAME
		  , BYR_COM_NAME
		  , BYR_COM_TYPE
		  , BYR_COM_CLASSIFY 
		  , BYR_COM_ADDR
		  , BYR_EMP_NAME
		  , BYR_EMAIL
		  , SUP_AMOUNT 
		  , TAX_AMOUNT
		  , TOTAL_AMOUNT
		  , TOTAL_QUANTITY
		  , REMARK
		  , CREATED_BY
		  , CREATION_DATE
		  , LAST_UPDATED_BY
		  , LAST_UPDATE_DATE
		  , DTI_MSG
		  , AMEND_CODE
		  , STATUS
		  , ORI_ISSUE_ID
		)
		VALUES
		( 
		    #{CONVERSATION_ID}
		  , #{SUPBUY_TYPE}			  
		  , #{DIRECTION}
		  , TO_DATE(#{DTI_WDATE},'YYYYMMDD')
		  , #{DTI_TYPE} 
		  , #{TAX_DEMAND}
		  , #{ISSUE_ID}
		  , #{SEQ_ID}
		  , #{SUP_COM_REGNO}
		  , #{SUP_REP_NAME}
		  , #{SUP_COM_NAME}
		  , #{SUP_COM_CLASSIFY}
		  , #{SUP_COM_ADDR}
		  , #{SUP_EMP_NAME}
		  , #{SUP_EMAIL}
		  , #{BYR_COM_REGNO}
		  , #{BYR_REP_NAME}
		  , #{BYR_COM_NAME}
		  , #{BYR_COM_TYPE}
		  , #{BYR_COM_CLASSIFY}
		  , #{BYR_COM_ADDR}
		  , #{BYR_EMP_NAME}
		  , #{BYR_EMAIL}
		  , #{SUP_AMOUNT}
		  , #{TAX_AMOUNT}
		  , #{TOTAL_AMOUNT}
		  , #{TOTAL_QUANTITY}
		  , #{REMARK}
		  , #{CREATED_BY}
		  , SYSDATE
		  , #{CREATED_BY}
		  , SYSDATE
		  , #{DTI_MSG}
		  , #{AMEND_CODE}
		  , 'C'
		  , #{ORI_ISSUE_ID}
		)

/*insertMasterCmClSBDtiItem*/

		INSERT INTO XXSB_DTI_ITEM
		( 
		    CONVERSATION_ID 
		  , SUPBUY_TYPE 
		  , DIRECTION 
		  , DTI_LINE_NUM 
		  , ITEM_NAME 
		  , UNIT_PRICE
		  , ITEM_QTY
		  , SUP_AMOUNT
		  , TAX_AMOUNT
		  , ITEM_GUBUN
		  , CREATED_BY
		  , CREATION_DATE
		  , LAST_UPDATED_BY
		  , LAST_UPDATE_DATE
		)
		VALUES
		( 
		    #{CONVERSATION_ID}
		  , #{SUPBUY_TYPE}			  
		  , #{DIRECTION}
		  , (SELECT NVL(MAX(DTI_LINE_NUM),0)+1 FROM XXSB_DTI_ITEM WHERE CONVERSATION_ID = #{CONVERSATION_ID})
		  , REPLACE(#{ITEM_NAME},'&','')
		  , ''
		  , #{ITEM_QTY}
		  , #{SUP_AMOUNT}
		  , #{TAX_AMOUNT}
		  , 'DTI'
		  , #{CREATED_BY}
		  , SYSDATE
		  , #{CREATED_BY}
		  , SYSDATE
		)

/*updateMasterCmClSBStatus*/

		UPDATE XXSB_DTI_STATUS
		SET LAST_UPDATED_BY = #{CREATED_BY}
		,  LAST_UPDATE_DATE = SYSDATE
		, DTI_STATUS = #{DTI_STATUS}
		 , SBDESCRIPTION =#{SBDESCRIPTION}
		WHERE CONVERSATION_ID = #{CONVERSATION_ID}

/*updateMasterCmClDelSBSMain*/

		UPDATE XXSB_DTI_MAIN
		SET STATUS = 'D'
		,  LAST_UPDATE_DATE = SYSDATE
		, LAST_UPDATED_BY = #{CREATED_BY}
		WHERE CONVERSATION_ID = #{CONVERSATION_ID}



/*saveXXSBDtiStatusInfo*/		 		
 UPDATE   XXSB_DTI_STATUS  
 SET RETURN_CODE =  #{st_error_code}  
 ,  RETURN_DESCRIPTION    = #{st_error_msg} 
 ,  LAST_UPDATE_DATE = SYSDATE
 ,  LAST_UPDATED_BY =  #{st_s_user_id}               
  WHERE CONVERSATION_ID     = #{st_ca_id}



/*errorSendSmartBill*/		 		
 UPDATE   XXSB_DTI_STATUS  
 SET RETURN_CODE =  DECODE(#{param2},'37002','30000' ,#{param2})  
 ,  RETURN_DESCRIPTION    = #{param3} 
 , DTI_STATUS = DECODE(#{param2},'37002','I' ,'E')
  WHERE CONVERSATION_ID     = #{param1}

/*updateMasterCmClArdtRemark*/

		UPDATE KEPTARDT
		SET REMARK = #{ARDT_REMARK} 
		, ISSUE_DATE = #{DTI_WDATE}
		WHERE TAX_BILL_NO = #{SEQ_ID}

