/*selectMasterCmClCheckXxSbDtiMain*/
	SELECT X.SEQ_ID 
	FROM XXSB_DTI_MAIN X
	WHERE X.STATUS != 'D'
	AND X.SEQ_ID = #{SEQ_ID}
